cards.solution:
import java.time.*;
import java.time.format.DateTimeFormatter;

public class Main {
    public static void main(String[] args) {
        String teks = "30/10/2026 21:15";
        DateTimeFormatter f = DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm");
        LocalDateTime w = LocalDateTime.parse(teks, f);
        System.out.println(w.plusHours(2).format(f));
    }
}

